-- LexAI 法律智能体平台数据库脚本

CREATE DATABASE IF NOT EXISTS lexai_db DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE lexai_db;

-- 用户表
CREATE TABLE IF NOT EXISTS users (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    username VARCHAR(50) UNIQUE NOT NULL COMMENT '用户名',
    password VARCHAR(255) NOT NULL COMMENT '密码',
    email VARCHAR(100) COMMENT '邮箱',
    phone VARCHAR(20) COMMENT '手机号',
    role VARCHAR(20) DEFAULT 'USER' COMMENT '角色',
    status VARCHAR(20) DEFAULT 'ACTIVE' COMMENT '状态',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_username (username),
    INDEX idx_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户表';

-- 法律咨询记录表
CREATE TABLE IF NOT EXISTS consultations (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    user_id BIGINT COMMENT '用户ID',
    question TEXT NOT NULL COMMENT '咨询问题',
    answer TEXT COMMENT 'AI回答',
    category VARCHAR(50) COMMENT '咨询类别：民事/刑事/行政/劳动',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
    INDEX idx_user_id (user_id),
    INDEX idx_category (category),
    INDEX idx_created_at (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='法律咨询记录表';

-- 案件分析表
CREATE TABLE IF NOT EXISTS cases (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    user_id BIGINT COMMENT '用户ID',
    case_name VARCHAR(200) COMMENT '案件名称',
    case_type VARCHAR(50) COMMENT '案件类型',
    case_description TEXT COMMENT '案件描述',
    analysis_result JSON COMMENT '分析结果',
    risk_level VARCHAR(20) COMMENT '风险等级：高/中/低',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
    INDEX idx_user_id (user_id),
    INDEX idx_case_type (case_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='案件分析表';

-- 合同审查表
CREATE TABLE IF NOT EXISTS contracts (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    user_id BIGINT COMMENT '用户ID',
    contract_name VARCHAR(200) COMMENT '合同名称',
    contract_type VARCHAR(50) COMMENT '合同类型：劳动合同/租赁合同/买卖合同',
    content TEXT COMMENT '合同内容',
    review_result JSON COMMENT '审查结果',
    risk_points JSON COMMENT '风险点列表',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
    INDEX idx_user_id (user_id),
    INDEX idx_contract_type (contract_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合同审查表';

-- 法律文书表
CREATE TABLE IF NOT EXISTS documents (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    user_id BIGINT COMMENT '用户ID',
    doc_type VARCHAR(50) COMMENT '文书类型：起诉状/答辩状/合同等',
    title VARCHAR(200) COMMENT '文书标题',
    content TEXT COMMENT '文书内容',
    template_id BIGINT COMMENT '模板ID',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
    INDEX idx_user_id (user_id),
    INDEX idx_doc_type (doc_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='法律文书表';

-- 案例库表
CREATE TABLE IF NOT EXISTS case_library (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    case_title VARCHAR(200) COMMENT '案例标题',
    case_type VARCHAR(50) COMMENT '案例类型',
    case_date DATE COMMENT '案件发生时间',
    case_region VARCHAR(100) COMMENT '案件发生地域',
    court VARCHAR(100) COMMENT '法院',
    cited_laws JSON COMMENT '引用法条',
    case_summary TEXT COMMENT '案例摘要',
    judgment_result TEXT COMMENT '判决结果',
    judgment_reason TEXT COMMENT '判决理由',
    key_points TEXT COMMENT '关键要点',
    similar_cases JSON COMMENT '相似案例',
    case_text TEXT COMMENT '案例全文',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_case_type (case_type),
    INDEX idx_case_title (case_title),
    INDEX idx_case_date (case_date),
    UNIQUE KEY unique_case_title (case_title)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='案例库表';

use lexai_db;
CREATE TEMPORARY TABLE IF NOT EXISTS seed_case_library LIKE case_library;

INSERT INTO seed_case_library
(case_title, case_type, case_date, case_region, court, cited_laws, case_summary, judgment_result, judgment_reason, key_points, similar_cases, case_text)
